@page "/board"
@using sv_052b7ccc716646beba89153db604e05d.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Project Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
    </div>
}
else
{
    <BoardStats Total="@tasks.Count"
                ToDo="@GetTasksForStatus("To Do").Count"
                InProgress="@GetTasksForStatus("In Progress").Count"
                DoneCount="@GetTasksForStatus("Done").Count"
                Overdue="@tasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done")" />

    <TaskSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="kanban-board d-flex gap-3">
        <KanbanColumn Title="To Do"
                      Status="To Do"
                      Tasks="@GetFilteredTasksForStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnTaskMoved="HandleTaskMoved"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn Title="In Progress"
                      Status="In Progress"
                      Tasks="@GetFilteredTasksForStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnTaskMoved="HandleTaskMoved"
                      OnTaskCreated="HandleTaskCreated" />

        <KanbanColumn Title="Done"
                      Status="Done"
                      Tasks="@GetFilteredTasksForStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnTaskMoved="HandleTaskMoved"
                      OnTaskCreated="HandleTaskCreated" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly Dictionary<string, string> MoveLeftMap = new()
    {
        ["In Progress"] = "To Do",
        ["Done"] = "In Progress"
    };

    private static readonly Dictionary<string, string> MoveRightMap = new()
    {
        ["To Do"] = "In Progress",
        ["In Progress"] = "Done"
    };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForStatus(string status)
        => tasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForStatus(string status)
        => tasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchText) || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleTaskMoved((TaskItem Task, string Direction) move)
    {
        var newStatus = move.Direction == "left"
            ? MoveLeftMap.GetValueOrDefault(move.Task.Status)
            : MoveRightMap.GetValueOrDefault(move.Task.Status);

        if (newStatus is null) return;

        try
        {
            await TaskService.UpdateTaskStatusAsync(move.Task.Id, newStatus);
            var index = tasks.FindIndex(t => t.Id == move.Task.Id);
            if (index >= 0)
            {
                tasks[index] = move.Task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleTaskCreated((string Title, string Assignee, string Priority, DateTime DueDate, string Status) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            tasks.Add(newTask with { Status = data.Status });
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

.kanban-board {
    overflow-x: auto;
}

.kanban-column {
    flex: 1;
