toolArgs.file_text:
.kanban-board {
    overflow-x: auto;
}

.kanban-column {
    flex: 1;
    min-width: 280px;
    background: #f8f9fa;
    border-radius: 8px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
}

.kanban-column-header h5 {
    margin: 0 0 0.75rem 0;
}

.kanban-column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

.kanban-column-footer {
    margin-top: 0.75rem;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.9rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background-color: #dc3545;
    color: #fff;
}

.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-low {
    background-color: #198754;
    color: #fff;
}

.task-card-body {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.5rem;
}

.task-card-actions {
    display: flex;
    gap: 0.5rem;
}

.add-task-form {
    background: #fff;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    padding: 0.75rem;
}

